To integrate PM2 into your FastAPI application, you can use a Python wrapper like the [PM2 Python Library](https://github.com/y4kupkaya/PM2) to avoid raw shell commands.
FastAPI PM2 Management Router
This router provides standard CRUD-like operations (Start, List, Stop, Delete) and a specific endpoint for retrieving logs.
```python
from fastapi import APIRouter, HTTPExceptionfrom pydantic import BaseModelfrom pm2 import PM2Manager  # requires: pip install pm2-python-libraryimport subprocess
router = APIRouter(prefix="/processes", tags=["Process Management"])pm2 = PM2Manager()
class ProcessCreate(BaseModel):
    name: str
    script: str
    interpreter: str = "python3"

@router.post("/start")async def start_process(config: ProcessCreate):
    """Create/Start a new process (Create)"""
    try:
        # PM2 auto-detects interpreters but can be explicit
        res = pm2.start_app(script=config.script, name=config.name, interpreter=config.interpreter)
        return {"message": f"Process {config.name} started", "status": "online"}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@router.get("/")async def list_processes():
    """List all managed processes (Read)"""
    # Returns a list of process objects with status, memory, and CPU
    return [
        {
            "name": p.name,
            "status": p.status,
            "memory_mb": p.metrics.memory_mb,
            "cpu_percent": p.metrics.cpu
        } for p in pm2.list_processes()
    ]

@router.post("/{name}/stop")async def stop_process(name: str):
    """Stop a running process (Update/Action)"""
    try:
        # Standard PM2 stop command via manager
        pm2.stop(name)
        return {"message": f"Process {name} stopped"}
    except Exception:
        raise HTTPException(status_code=404, detail="Process not found")

@router.delete("/{name}")async def delete_process(name: str):
    """Delete a process from the PM2 list (Delete)"""
    try:
        pm2.delete(name)
        return {"message": f"Process {name} deleted"}
    except Exception:
        raise HTTPException(status_code=404, detail="Process not found")

@router.get("/{name}/logs")async def get_logs(name: str, lines: int = 50):
    """Read the last X log entries for a process"""
    try:
        # Uses CLI command to fetch exact tail length
        command = ["pm2", "logs", name, "--lines", str(lines), "--nostream", "--raw"]
        result = subprocess.run(command, capture_output=True, text=True)

        if result.returncode != 0:
            raise HTTPException(status_code=404, detail="Process logs not found")

        return {"process": name, "lines": lines, "output": result.stdout.strip()}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))
```
Key Implementation Details

* Log Handling: While the PM2 Python library manages process state, retrieving specific "tail" log counts is most reliably done via the pm2 logs --lines X --nostream CLI command.
* Auto-Restart: By default, PM2 will automatically restart any process started via this API if it crashes.
* Prerequisites: Ensure PM2 is installed globally on your Debian system (npm install -g pm2) before running the FastAPI app.

